<?php require 'includes/functions.php';if(!empty($_SESSION['admin']))go('admin/dashboard.php');if($_SERVER['REQUEST_METHOD']==='POST'){$q=db()->prepare('SELECT * FROM admins WHERE username=?');$q->execute([trim($_POST['username']??'')]);$a=$q->fetch();if($a&&password_verify($_POST['password']??'',$a['password'])){$_SESSION['admin']=['id'=>$a['id'],'name'=>$a['name']];go('admin/dashboard.php');}flash('danger','Invalid admin credentials.');}$pageTitle='Admin Login';require 'includes/header.php'; ?>
